// Ground truth for the two vector operations in src/crash.js flagged as
// handedness-sensitive in docs/UNITY_PORT.md's crash-camera note: the one
// true cross product (the death-cam's side-step off the "back" vector,
// src/crash.js:130) and the wreck's reflect off a wall normal
// (src/crash.js:108-109).
//
// This does NOT instantiate the real CrashSequence class: its random angVel/
// debris scatter are generated by a different PRNG on each side of the port
// and are not meaningfully comparable number-for-number. What IS comparable,
// and is exactly the thing the port has to get right, are these two
// deterministic formulas.
//
// This script does TWO jobs, kept in SEPARATE output lines on purpose:
//   1. CRASHM_CHECK lines are this script's OWN self-verification (proving
//      the cross-product operand swap and the reflect's mirror-invariance
//      algebraically, using THREE's own cross()/reflect(), no Unity
//      involved) — it exits 1 if any of these fail, so a mistake HERE is
//      caught before it could ever be blamed on the C# port.
//   2. CRASHM lines carry ONLY the numbers CrashProbe.cs also prints
//      (mback_x/y/z, side_x/y/z for cross*; r_x/y/z for reflect*), in
//      EXACTLY that shape, for tools/unity_port_check.py to diff. The
//      original version of this file folded the self-check booleans
//      (handWrittenIsCross=true, swapMatches=true, mirrorInvariant=true,
//      ...) into these SAME lines — harmless as prose, but it changed the
//      line's SKELETON (tools/unity_port_check.py's term for "text with
//      numbers blanked") so it could never match CrashProbe.cs's shorter
//      line, and every one of the 8 pairs silently fell through as
//      "unmatched" instead of being diffed. Keeping the two concerns apart
//      is what makes both of them a real gate.
//
//   CRASHM_CHECK has NO C# counterpart, and cannot get one: it proves the
//   JS's own HAND-WRITTEN formula (src/crash.js:130's
//   `new THREE.Vector3(-back.z, 0, back.x)`) is algebraically back.cross(up)
//   — an algebra fact about THAT formula, derived with THREE's own cross(),
//   never touching Unity. CrashSequence.cs carries no hand-written equivalent
//   to re-derive this against: Core/CrashSequence.cs:194 calls
//   `Vector3.Cross(Vector3.up, back)` directly, so there is no second,
//   independently-written formula on the C# side for a "handWrittenIsCross"-
//   style check to compare against — porting these 3 lines to C# would mean
//   inventing a redundant hand-rolled cross just to re-prove it equals
//   Vector3.Cross, i.e. testing the test, not the port. So these stay
//   JS-only, and (unlike an earlier version of this file) are now marked
//   with the JSONLY prefix tools/unity_port_check.py's one_sided() convention
//   requires: without it, these 18 lines (3 per cross id x 5 + 1 per reflect
//   id x 3) read as 18 "no C# line matching" mismatches and FAIL the probe,
//   even though every one of the 8 real CRASHM pairs agrees to the number.
//
//   node tools/_probe_crashmath.mjs
import * as THREE from 'three';

const f = (n) => n.toFixed(6);
let selfCheckFailed = false;
function check(id, label, ok) {
  console.log(`JSONLY CRASHM_CHECK id=${id} check=${label} ok=${ok ? 1 : 0}`);
  if (!ok) selfCheckFailed = true;
}

const BACKS = [
  [0.6, 0, 0.8], [1, 0, 0], [0, 0, 1], [-0.3, 0, 0.95], [0.707, 0, -0.707],
];
BACKS.forEach(([x, y, z], i) => {
  const back = new THREE.Vector3(x, y, z).normalize();
  const up = new THREE.Vector3(0, 1, 0);

  // The JS's hand-written formula: src/crash.js:130
  // `new THREE.Vector3(-back.z, 0, back.x)`.
  const sideHandWritten = new THREE.Vector3(-back.z, 0, back.x);
  // Confirm it IS algebraically back×up (THREE's a.cross(b) = a×b, done in place on a clone).
  const sideAsCross = back.clone().cross(up);
  check(`cross${i}`, 'handWrittenIsCross', sideHandWritten.distanceTo(sideAsCross) < 1e-9);

  // GAME FRAME -> UNITY FRAME: mirror X on the input (back), the same way
  // GeoFrame.ToUnity mirrors every stored position/direction. The CORRECT
  // mirrored side vector is the game-frame result ALSO mirrored on X.
  const mBack = new THREE.Vector3(-back.x, back.y, back.z);
  const sideExpected = new THREE.Vector3(-sideHandWritten.x, sideHandWritten.y, sideHandWritten.z);

  // The claim under test: Unity should compute cross(up, mBack) -- SWAPPED
  // operands from the JS's back×up -- to land on sideExpected.
  const sideFromSwappedCross = new THREE.Vector3().crossVectors(up, mBack);
  check(`cross${i}`, 'swapMatches', sideFromSwappedCross.distanceTo(sideExpected) < 1e-9);
  // And the claim it is GUARDING against: the UN-swapped cross (same operand
  // order as the JS) should NOT match -- it should be the negative.
  const sideFromUnswappedCross = new THREE.Vector3().crossVectors(mBack, up);
  check(`cross${i}`, 'unswappedIsNegative',
    sideFromUnswappedCross.distanceTo(sideExpected.clone().negate()) < 1e-9);

  // The comparable line — SAME shape as CrashProbe.cs's `CRASHM id=cross{i} ...`.
  console.log(`CRASHM id=cross${i} mback_x=${f(mBack.x)} mback_y=${f(mBack.y)} mback_z=${f(mBack.z)} ` +
    `side_x=${f(sideExpected.x)} side_y=${f(sideExpected.y)} side_z=${f(sideExpected.z)}`);
});

const CASES = [
  { v: [10, -2, 4], n: [1, 0, 0] },
  { v: [-6, 3, 9], n: [0.6, 0, 0.8] },
  { v: [0, 5, -12], n: [0, 0, 1] },
];
CASES.forEach(({ v, n }, i) => {
  // src/crash.js:108-109 `vel.reflect(n)`.
  const vg = new THREE.Vector3(...v);
  const ng = new THREE.Vector3(...n).normalize();
  const rg = vg.clone().reflect(ng); // game frame
  const reflectThenMirror = new THREE.Vector3(-rg.x, rg.y, rg.z);

  const vu = new THREE.Vector3(-v[0], v[1], v[2]); // mirror inputs first
  const nu = new THREE.Vector3(-n[0], n[1], n[2]).normalize();
  const mirrorThenReflect = vu.clone().reflect(nu); // SAME formula, no operand swap

  check(`reflect${i}`, 'mirrorInvariant', reflectThenMirror.distanceTo(mirrorThenReflect) < 1e-9);

  console.log(`CRASHM id=reflect${i} r_x=${f(mirrorThenReflect.x)} r_y=${f(mirrorThenReflect.y)} ` +
    `r_z=${f(mirrorThenReflect.z)}`);
});

if (selfCheckFailed) {
  console.error('FAIL - a CRASHM_CHECK self-verification failed (see ok=0 above); '
    + 'the ground truth itself is suspect, independent of any C# diff.');
  process.exit(1);
}
